const all: any[] = [];
for (let page = 1; page <= 20; page++) {
  const res: any = await tools.list_issues({ repo: "acme/api", state: "open", label: "security", page });
  const items = Array.isArray(res) ? res : (res?.items ?? res?.issues ?? []);
  if (!items.length) break;
  all.push(...items);
  if (items.length < 50) break;
}

const seen = new Set<number>();
const targets = all.filter((i: any) => {
  if (seen.has(i.number)) return false;
  seen.add(i.number);
  const hasLabel = (i.labels ?? []).some((l: any) => l.name === "security");
  const unassigned = !i.assignee && (!Array.isArray(i.assignees) || i.assignees.length === 0);
  const isOpen = i.state === "open";
  const isIssue = !i.pull_request;
  return hasLabel && unassigned && isOpen && isIssue && i.user?.login;
});

const results: any[] = [];
for (const i of targets) {
  try {
    const r = await tools.assign({ repo: "acme/api", number: i.number, assignee: i.user.login });
    results.push({ number: i.number, assignee: i.user.login, ok: true, r });
  } catch (e: any) {
    results.push({ number: i.number, assignee: i.user.login, ok: false, error: String(e?.message ?? e) });
  }
}

return { listed: all.length, targetCount: targets.length, targets: targets.map((i: any) => ({ number: i.number, opener: i.user.login })), results };
